1	// This file pins down the independent-copy guarantee for the two lists
2	// embedded in an audited decision:
3	//
4	//   - Request.Subject.Roles — the subject's roles are part of the audited
5	//     request even though they take no part in organization policy
6	//     authorization, and their submitted order is historical fact.
7	//   - Decision.Matched — the complete matched-policy list is part of the
8	//     decision explanation an auditor must be able to reconstruct.
9	//
10	// The store promises to save its own detached copy when Decide is called
11	// and to hand out detached copies from audit query, paging, export,
12	// archive and recheck entry points. These tests exercise that promise
13	// through the public API only: after a decision the caller may rewrite or
14	// extend the request roles and matched list they hold, and after reading a
15	// record they may edit the same lists in every material they received;
16	// the stored history, a fresh read and a previously retained copy must all
17	// keep the decision-time content. A regression that aliases either list
18	// into caller memory fails here no matter which read path exposes it.
19	package darksafe
20	
21	import (
22		"errors"
23		"reflect"
24		"strings"
25		"testing"
26	)
27	
28	// listIsolationRoles is a non-empty role list exercising Chinese, leading,
29	// trailing and internal spaces, and a lone non-UTF-8 byte. Roles never
30	// authorize anything, so the decision is driven by policies while the
31	// roles survive purely as preserved request content.
32	func listIsolationRoles() []string {
33		return []string{"角色 alpha", "  前后 空格  ", "原" + invalidByte + "始"}
34	}
35	
36	// listIsolationPolicies gives u2 exactly one allow hit (whose id carries a
37	// non-UTF-8 byte) and u1 a deny hit together with allow hits, so the deny
38	// decision still carries a complete, ordered matched list.
39	func listIsolationPolicies() []Policy {
40		return []Policy{
41			{ID: "z-allow 许", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
42			{ID: "a-deny 拒", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny},
43			{ID: "m-allow 中" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true},
44			{ID: "p-allow 通" + invalidByte, Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectAllow},
45		}
46	}
47	
48	// roleRequest builds one legal request for the subject with the given
49	// roles, using a fresh backing array so each fixture request is independent.
50	func roleRequest(subject string, roles []string) OrgRequest {
51		req := request("acme", subject, "r1", "org/a", "read")
52		req.Subject.Roles = append([]string(nil), roles...)
53		return req
54	}
55	
56	// assertDecisionListContent checks the complete decision-time content the
57	// history must still show: role order, matched list, effect, reason and
58	// the version actually used.
59	func assertDecisionListContent(t *testing.T, r *AuditRecord, seq int, wantRoles []string, want Decision) {
60		t.Helper()
61		if r.Seq != seq || r.Kind != AuditDecision || r.Decision == nil {
62			t.Fatalf("seq %d: not a decision record: %+v", seq, r)
63		}
64		if got := r.Decision.Request.Subject.Roles; !reflect.DeepEqual(got, wantRoles) {
65			t.Fatalf("seq %d roles = %q, want decision-time %q", seq, got, wantRoles)
66		}
67		got := r.Decision.Decision
68		if got.Allowed != want.Allowed {
69			t.Fatalf("seq %d allowed = %v, want %v", seq, got.Allowed, want.Allowed)
70		}
71		if got.Reason != want.Reason {
72			t.Fatalf("seq %d reason = %q, want %q", seq, got.Reason, want.Reason)
73		}
74		if got.Version != want.Version {
75			t.Fatalf("seq %d version = %d, want %d", seq, got.Version, want.Version)
76		}
77		if !reflect.DeepEqual(got.Matched, want.Matched) {
78			t.Fatalf("seq %d matched = %q, want %q", seq, got.Matched, want.Matched)
79		}
80	}
81	
82	// recordBySeq returns the decision record at seq, failing the test when it
83	// is absent or not a decision.
84	func recordBySeq(t *testing.T, recs []AuditRecord, seq int) *AuditRecord {
85		t.Helper()
86		for i := range recs {
87			if recs[i].Seq == seq {
88				if recs[i].Kind != AuditDecision || recs[i].Decision == nil {
89					t.Fatalf("seq %d is not a decision", seq)
90				}
91				return &recs[i]
92			}
93		}
94		t.Fatalf("no record at seq %d among %d records", seq, len(recs))
95		return nil
96	}
97	
98	// TestDecideListCopiesSurviveCallerEdits covers the primary promise: once
99	// Decide returned, the caller may replace role names in the request they
100	// submitted, append roles, and rewrite or extend the matched policies in
101	// the decision they got back. Both an allow decision and a deny decision
102	// that carries matched policies must keep independent copies — not only
103	// the authorization success. Every later read (export, paged query,
104	// online and offline recheck) must still show the decision-time role
105	// order, complete matched list, effect, reason and actual version.
106	func TestDecideListCopiesSurviveCallerEdits(t *testing.T) {
107		s := NewStore()
108		if _, err := s.Publish("acme", 0, listIsolationPolicies()); err != nil {
109			t.Fatal(err)
110		}
111		roles := listIsolationRoles()
112		allowReq := roleRequest("u2", roles)
113		denyReq := roleRequest("u1", roles)
114	
115		allowD := s.Decide("acme", allowReq) // seq 2, allowed
116		denyD := s.Decide("acme", denyReq)   // seq 3, denied with matches
117		if !allowD.Allowed || allowD.Version != 1 || len(allowD.Matched) != 1 {
118			t.Fatalf("setup allow decision = %+v", allowD)
119		}
120		if denyD.Allowed || denyD.Reason != "matched deny policy" ||
121			denyD.Version != 1 || len(denyD.Matched) != 3 {
122			t.Fatalf("setup deny decision = %+v, want a denial carrying 3 matches", denyD)
123		}
124		// Snapshot what history must remember before the caller edits anything.
125		wantRoles := append([]string(nil), roles...)
126		wantAllow := cloneDecisionValue(allowD)
127		wantDeny := cloneDecisionValue(denyD)
128	
129		// The caller rewrites the request they submitted...
130		allowReq.Subject.Roles[0] = "替换后的角色"
131		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "新增角色")
132		denyReq.Subject.Roles[2] = "被改写的原始字节"
133		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "另一个新增角色")
134		// ...and the returned decisions they hold.
135		allowD.Matched[0] = "forged-policy"
136		allowD.Matched = append(allowD.Matched, "ghost-policy")
137		denyD.Matched[0] = "forged-policy"
138		denyD.Matched = append(denyD.Matched, "ghost-policy")
139	
140		// Full export: stored content is byte-for-byte the decision-time content.
141		recs, cp, err := s.AuditExport("acme", 0)
142		if err != nil {
143			t.Fatal(err)
144		}
145		if len(recs) != 3 {
146			t.Fatalf("records = %d, want 3; reads/edits must not append", len(recs))
147		}
148		if err := VerifyAudit("acme", recs, cp); err != nil {
149			t.Fatalf("stored chain changed through caller list edits: %v", err)
150		}
151		assertDecisionListContent(t, &recs[1], 2, wantRoles, wantAllow)
152		assertDecisionListContent(t, &recs[2], 3, wantRoles, wantDeny)
153	
154		// Paged query returns the same content.
155		paged := drainAudit(t, s, "acme", AuditDecision, "")
156		if len(paged) != 2 {
157			t.Fatalf("paged decisions = %d, want 2", len(paged))
158		}
159		assertDecisionListContent(t, recordBySeq(t, paged, 2), 2, wantRoles, wantAllow)
160		assertDecisionListContent(t, recordBySeq(t, paged, 3), 3, wantRoles, wantDeny)
161	
162		// Replaying by the stored record still reaches the original conclusion.
163		gotAllow, err := s.RecheckDecision("acme", 2)
164		if err != nil || !reflect.DeepEqual(gotAllow, wantAllow) {
165			t.Fatalf("online allow recheck = %+v, %v, want %+v", gotAllow, err, wantAllow)
166		}
167		gotDeny, err := s.RecheckDecision("acme", 3)
168		if err != nil || !reflect.DeepEqual(gotDeny, wantDeny) {
169			t.Fatalf("online deny recheck = %+v, %v, want %+v", gotDeny, err, wantDeny)
170		}
171	
172		for _, seq := range []int{2, 3} {
173			review, err := RecheckDecisionOffline("acme", recs, cp, seq)
174			if err != nil {
175				t.Fatalf("seq %d offline review: %v", seq, err)
176			}
177			if !review.Consistent {
178				t.Fatalf("seq %d review inconsistent: %+v", seq, review)
179			}
180		}
181		if rv := mustOfflineReview(t, recs, cp, 2); !reflect.DeepEqual(rv.Original, wantAllow) ||
182			!reflect.DeepEqual(rv.Recomputed, wantAllow) {
183			t.Fatalf("allow offline review = %+v, want %+v", rv, wantAllow)
184		}
185		if rv := mustOfflineReview(t, recs, cp, 3); !reflect.DeepEqual(rv.Original, wantDeny) ||
186			!reflect.DeepEqual(rv.Recomputed, wantDeny) {
187			t.Fatalf("deny offline review = %+v, want %+v", rv, wantDeny)
188		}
189	}
