331	// rewriteLists simulates the caller editing one record copy: overwrite a
332	// role name and a matched policy name, then append entries to both lists.
333	// Lists must be non-empty, which every target decision carries.
334	func rewriteLists(r *AuditRecord) {
335		roles := r.Decision.Request.Subject.Roles
336		roles[0] = "forged-role"
337		r.Decision.Request.Subject.Roles = append(roles, "ghost-role")
338		matched := r.Decision.Decision.Matched
339		matched[0] = "forged-policy"
340		r.Decision.Decision.Matched = append(matched, "ghost-policy")
341	}
