595	// TestEmptyRoleListWithCapacityIsolated is the regression for capacious
596	// empty role lists. A subject completes an allow, a no-match denial and a
597	// disabled-subject envelope denial, each with a non-nil empty role list that
598	// still has spare capacity. The caller obtains audit material two at a time
599	// from the first query, a later page and a full export, and appends a
600	// distinct temporary role to each copy; appending to one result must never
601	// overwrite another's role, and appending to the originally submitted list
602	// must reach no material. A fresh read still shows a non-nil empty list with
603	// the unchanged decision (allowed, reason, matched policies, version); nil
604	// roles stay nil. Checkpoints and fingerprints are unchanged by the fix, the
605	// material still verifies, archives, reads back and reviews offline.
606	func TestEmptyRoleListWithCapacityIsolated(t *testing.T) {
607		s := NewStore()
608		policies := []Policy{{ID: "p-allow", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow}}
609		if _, err := s.Publish("acme", 0, policies); err != nil { // seq 1, v1
610			t.Fatal(err)
611		}
612	
613		allowReq := request("acme", "u1", "r1", "org/a", "read")
614		allowReq.Subject.Roles = capaciousEmptyRoles()
615		denyReq := request("acme", "u9", "r1", "org/a", "read")
616		denyReq.Subject.Roles = capaciousEmptyRoles()
617		disabledReq := request("acme", "u3", "r1", "org/a", "read")
618		disabledReq.Subject.Roles = capaciousEmptyRoles()
619		disabledReq.Subject.Disabled = true
620	
621		allowD := s.Decide("acme", allowReq)     // seq 2, allowed
622		denyD := s.Decide("acme", denyReq)       // seq 3, no-match denial
623		envDeny := s.Decide("acme", disabledReq) // seq 4, envelope denial
624		if !allowD.Allowed || allowD.Version != 1 || !reflect.DeepEqual(allowD.Matched, []string{"p-allow"}) {
625			t.Fatalf("setup allow = %+v", allowD)
626		}
627		if denyD.Allowed || denyD.Reason != "no matching allow policy" || denyD.Version != 1 || denyD.Matched == nil {
628			t.Fatalf("setup no-match denial = %+v, want non-nil empty matched", denyD)
629		}
630		if envDeny.Allowed || envDeny.Reason != "subject is disabled" || envDeny.Version != 0 || envDeny.Matched != nil {
631			t.Fatalf("setup envelope denial = %+v, want nil matched, version 0", envDeny)
632		}
633		want := map[int]Decision{
634			2: cloneDecisionValue(allowD),
635			3: cloneDecisionValue(denyD),
636			4: cloneDecisionValue(envDeny),
637		}
638	
639		// The caller later appends to the lists it submitted; no audit material
640		// may observe that.
641		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "caller-allow-role")
642		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "caller-deny-role")
643		disabledReq.Subject.Roles = append(disabledReq.Subject.Roles, "caller-disabled-role")
644	
645		exportA, cp, err := s.AuditExport("acme", 0)
646		if err != nil {
647			t.Fatal(err)
648		}
649		exportB, _, err := s.AuditExport("acme", 0)
650		if err != nil {
651			t.Fatal(err)
652		}
653		if err := VerifyAudit("acme", exportA, cp); err != nil {
654			t.Fatalf("export chain: %v", err)
655		}
656	
657		// Page by decision kind: seq 1 is the publish (filtered out), so a
658		// pageSize of 1 puts only seq 2 on the first page and seq 3, 4 on the
659		// later page.
660		pageA, err := s.AuditQuery("acme", 1, 1, AuditDecision, "")
661		if err != nil {
662			t.Fatal(err)
663		}
664		pageB, err := s.AuditPage(pageA.Checkpoint, pageA.Next, 2, AuditDecision, "")
665		if err != nil {
666			t.Fatal(err)
667		}
668		if len(pageA.Records) != 1 || pageA.Records[0].Seq != 2 {
669			t.Fatalf("first query page layout = %+v", pageA.Records)
670		}
671		if len(pageB.Records) != 2 || pageB.Records[0].Seq != 3 || pageB.Records[1].Seq != 4 || pageB.Next != 0 {
672			t.Fatalf("later page layout = %+v next=%d", pageB.Records, pageB.Next)
673		}
674	
675		// Every read shows a non-nil empty role list.
676		for _, seq := range []int{2, 3, 4} {
677			requireNonNilEmptyRoles(t, "exportA", recordBySeq(t, exportA, seq).Decision.Request.Subject.Roles)
678			requireNonNilEmptyRoles(t, "exportB", recordBySeq(t, exportB, seq).Decision.Request.Subject.Roles)
679		}
680		requireNonNilEmptyRoles(t, "query seq2", pageA.Records[0].Decision.Request.Subject.Roles)
681		requireNonNilEmptyRoles(t, "page seq3", pageB.Records[0].Decision.Request.Subject.Roles)
682		requireNonNilEmptyRoles(t, "page seq4", pageB.Records[1].Decision.Request.Subject.Roles)
683	
684		// Append a distinct temporary role to the same decision in two export
685		// copies. A shared backing array makes the second append overwrite the
686		// first — exactly the reported defect.
687		aRoles := recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles
688		bRoles := recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles
689		aRoles = append(aRoles, "临时角色甲")
690		bRoles = append(bRoles, "临时角色乙")
691		// Assign back: append may or may not reuse the slice header, but the
692		// record copy must be the one the caller is editing.
693		recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles = aRoles
694		recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles = bRoles
695		if got := recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"临时角色甲"}) {
696			t.Fatalf("export A seq2 roles = %q, want [临时角色甲]", got)
697		}
698		if got := recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"临时角色乙"}) {
699			t.Fatalf("export B seq2 roles = %q, want [临时角色乙]; read copies shared storage", got)
700		}
701	
702		// Query page and later page each get their own appendable copy.
703		pageA.Records[0].Decision.Request.Subject.Roles = append(pageA.Records[0].Decision.Request.Subject.Roles, "query-role")
704		pageB.Records[0].Decision.Request.Subject.Roles = append(pageB.Records[0].Decision.Request.Subject.Roles, "page-deny-role")
705		pageB.Records[1].Decision.Request.Subject.Roles = append(pageB.Records[1].Decision.Request.Subject.Roles, "page-disabled-role")
706	
707		// Cross-read isolation: an edit anywhere is invisible to every other
708		// read of the same sequence, and the caller's post-hoc appends never
709		// appear.
710		untouched := []struct {
711			label string
712			roles []string
713		}{
714			{"exportA seq3", recordBySeq(t, exportA, 3).Decision.Request.Subject.Roles},
715			{"exportA seq4", recordBySeq(t, exportA, 4).Decision.Request.Subject.Roles},
716			{"exportB seq3", recordBySeq(t, exportB, 3).Decision.Request.Subject.Roles},
717			{"exportB seq4", recordBySeq(t, exportB, 4).Decision.Request.Subject.Roles},
718			{"query seq2", pageA.Records[0].Decision.Request.Subject.Roles},
719			{"page seq3", pageB.Records[0].Decision.Request.Subject.Roles},
720			{"page seq4", pageB.Records[1].Decision.Request.Subject.Roles},
721		}
722		for i, c := range untouched {
723			var leaked bool
724			switch {
725			case i <= 3:
726				leaked = c.roles == nil || len(c.roles) != 0
727			default:
728				leaked = len(c.roles) != 1
729			}
730			if leaked {
731				t.Fatalf("%s roles = %q, other copies' edits leaked across reads", c.label, c.roles)
732			}
733		}
734		for name, recs := range map[string][]AuditRecord{"exportA": exportA, "exportB": exportB} {
735			for _, seq := range []int{2, 3, 4} {
736				for _, got := range recordBySeq(t, recs, seq).Decision.Request.Subject.Roles {
737					if strings.HasPrefix(got, "caller-") {
738						t.Fatalf("%s seq %d leaked the caller's post-hoc role %q", name, seq, got)
739					}
740				}
741			}
742		}
743	
744		// A fresh read after all edits still shows non-nil empty lists, the same
745		// checkpoint and the unchanged decision content.
746		fresh, freshCP, err := s.AuditExport("acme", 0)
747		if err != nil {
748			t.Fatal(err)
749		}
750		if freshCP != cp {
751			t.Fatalf("checkpoint changed after caller edits: %+v vs %+v", freshCP, cp)
752		}
753		if err := VerifyAudit("acme", fresh, cp); err != nil {
754			t.Fatalf("fresh export fails original checkpoint: %v", err)
755		}
756		for _, seq := range []int{2, 3, 4} {
757			r := recordBySeq(t, fresh, seq)
758			requireNonNilEmptyRoles(t, "fresh", r.Decision.Request.Subject.Roles)
759			if !decisionsEqual(r.Decision.Decision, want[seq]) {
760				t.Fatalf("fresh seq %d decision = %+v, want %+v", seq, r.Decision.Decision, want[seq])
761			}
762			if got, err := s.RecheckDecision("acme", seq); err != nil || !decisionsEqual(got, want[seq]) {
763				t.Fatalf("online recheck seq %d = %+v, %v", seq, got, err)
764			}
765			if rv, err := RecheckDecisionOffline("acme", fresh, cp, seq); err != nil || !rv.Consistent {
766				t.Fatalf("offline review seq %d = %+v, %v", seq, rv, err)
767			}
768		}
769		// Offline review on role-edited material must refuse it: roles are part
770		// of the fingerprint, so that copy is tampered material and fails the
771		// whole-material chain check with ErrInvalidRange (never silently
772		// reviewed). The store's own history is unaffected.
773		if _, err := RecheckDecisionOffline("acme", exportB, cp, 2); !errors.Is(err, ErrInvalidRange) {
774			t.Fatalf("offline review of role-edited material err = %v, want ErrInvalidRange", err)
775		}
776	
777		// Archive round trip preserves the non-nil empty shape and each decode is
778		// an independent copy.
779		archive, err := EncodeAuditArchive("acme", fresh, cp)
780		if err != nil {
781			t.Fatal(err)
782		}
783		d1, err := DecodeAuditArchive(archive, "acme", cp)
784		if err != nil {
785			t.Fatalf("decode 1: %v", err)
786		}
787		d2, err := DecodeAuditArchive(archive, "acme", cp)
788		if err != nil {
789			t.Fatalf("decode 2: %v", err)
790		}
791		for _, seq := range []int{2, 3, 4} {
792			requireNonNilEmptyRoles(t, "archive d1", recordBySeq(t, d1, seq).Decision.Request.Subject.Roles)
793			requireNonNilEmptyRoles(t, "archive d2", recordBySeq(t, d2, seq).Decision.Request.Subject.Roles)
794		}
795		recordBySeq(t, d1, 2).Decision.Request.Subject.Roles = append(recordBySeq(t, d1, 2).Decision.Request.Subject.Roles, "归档角色甲")
796		recordBySeq(t, d2, 2).Decision.Request.Subject.Roles = append(recordBySeq(t, d2, 2).Decision.Request.Subject.Roles, "归档角色乙")
797		if got := recordBySeq(t, d1, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"归档角色甲"}) {
798			t.Fatalf("archive d1 roles = %q", got)
799		}
800		if got := recordBySeq(t, d2, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"归档角色乙"}) {
801			t.Fatalf("archive d2 roles = %q; decodes shared storage", got)
802		}
803	
804		// nil roles stay genuinely nil and never collapse to empty.
805		nilReq := request("acme", "u7", "r1", "org/a", "read") // roles left nil
806		s.Decide("acme", nilReq)                               // seq 5
807		nilExport, _, err := s.AuditExport("acme", 0)
808		if err != nil {
809			t.Fatal(err)
810		}
811		if got := recordBySeq(t, nilExport, 5).Decision.Request.Subject.Roles; got != nil {
812			t.Fatalf("nil roles read back as %v", got)
813		}
814	
815		// Reads and caller edits appended nothing and changed no version.
816		if got := len(drainAudit(t, s, "acme", "", "")); got != 5 {
817			t.Fatalf("records = %d, want 5", got)
818		}
819		if v := s.CurrentVersion("acme"); v != 1 {
820			t.Fatalf("current version = %d, want 1", v)
821		}
822	}
823

